      border: 1px solid hsl(var(--border));
      border-radius: var(--radius);
      overflow: hidden;
      margin: 24px 0 0;
      font-size: 14.5px;
    }
.spec-table th {
      text-align: left;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
