.spec-table td:first-child { font-weight: 600; white-space: nowrap; }
.spec-table td.formula {
      font-family: 'JetBrains Mono', monospace;
      font-size: 13px;
      color: hsl(var(--muted-foreground));
      white-space: nowrap;
    }

.kicker {
